var b="url",c="1_1_10_1_【初始化-首单用户】日产_启辰-取送车活动2：取送车首单优惠活动（后台统一推送）.html",d="generationDate",e=new Date(1793958860914.44),f="defaultAdaptiveView",g="name",h="",i="size",j="width",k=0,l="height",m="adaptiveViews",n="sketchKeys",o="s0",p="variables",q="OnLoadVariable",r="page",s="packageId",t="b9784965f0254f948972e3aa001212ab",u="type",v="Axure:Page",w="1.1.10.1 【初始化-首单用户】日产/启辰-取送车活动2：取送车首单优惠活动（后台统一推送）",x="notes",y="annotations",z="fn",A="1",B="ownerId",C="9f516f22b4d340209b2b7dda2dd01547",D="label",E="* 业务版块：",F="交互说明",G="<p><span>默认勾选，不可编辑修改</span></p>",H="2",I="af3251f7fd6449e2aee3a6db56a46c68",J="后台统一推送",K="字段说明",L="<p><span style=\"color:#333333;\">按照设置的活动预热开始时间（无预热时间则活动开始时间），活动中心调卡券中心发券接口进行发券</span></p>",M="其他说明",N="<p><span>续保活动+后台统一推送，</span></p><p><span>可配置 CVT变速箱活动、超值购活动；</span></p><p><span><br></span></p><p><span>取送车活动+后台统一推送，</span></p><p><span>可配置 取送车双月活动、取送车退网店活动、取送车同城一口价、取送车特案客户活动</span></p>",O="3",P="85027e108de64e8cadf2bc9c240359cd",Q="用户行为触发",R="<p><span>用户行为触发卡券的逻辑：</span></p><p><span>活动中心定义活动规则，同步信息给业务系统；</span></p><p><span>当用户产生该行为，业务系统上报给活动中心，活动中心调卡券中心发券接口发放卡券给用户</span></p>",S="<p><span>选择续保活动+用户行为触发，</span></p><p><span>默认勾选OEM续保套餐活动</span></p>",T="4",U="a2904d584fb74aa19da48b5ef955dfb1",V="C端主动参与活动",W="<p><span>1-BIMC双月活动，</span></p><p><span>2-BIMC会员周活动，</span></p><p><span>3-BIMC单店机动券活动</span></p>",X="<p><span style=\"font-family:'PingFangSC-Regular', 'PingFang SC', sans-serif;color:#D9001B;\">C端活动，以卡券中心配置车型、门店为准</span></p><p><span>选择C端活动，</span></p><p><span>隐藏【基本信息-是否多张卡券】【活动车型取值】【活动门店取值】</span></p><p><span>隐藏【tab适用车型】、【tab适用门店】</span></p>",Y="5",Z="f787de5c6d7e45c7b40651f9844895fc",ba="互斥套餐",bb="<p><span style=\"font-family:'PingFangSC-Regular', 'PingFang SC', sans-serif;\">新活动可以通过卡券去互斥，这里需剔除已享有互斥套餐的客户，如五年双保套餐、心悦保养套餐、N延保等;</span></p><p><span style=\"font-family:'PingFangSC-Regular', 'PingFang SC', sans-serif;\">可多个互斥套餐；</span></p><p><span style=\"font-family:'PingFangSC-Regular', 'PingFang SC', sans-serif;\"><br></span></p><p><span>选择是--必填互斥套餐或互斥活动ID</span></p>",bc="6",bd="51f3464ae1724283be70cff03fedb195",be="卡券活动",bf="<p><span>售后一期</span></p><p><span>1、默认为卡券活动；</span></p><p><span>2、选项的厂家、店端，非必填</span></p>",bg="7",bh="86c691eee95a400c90361f8ba5848003",bi="英菲尼迪",bj="<p><span>应综合科韩紫燕和IS李金刚要求，品牌加英菲；</span></p><p><span>以后对接英菲的基础数据，</span></p><p><span>对接前按钮置灰，不可勾选</span></p>",bk="8",bl="00da48bc074b4e568c14adc05554670d",bm="* 触发方式：",bn="<p><span style=\"font-family:'微软雅黑', sans-serif;\">1、后台统一推送：</span></p><p><span style=\"font-family:'微软雅黑', sans-serif;\">活动中心调卡券中心的发券接口，对用户标签圈定的目标用户 进行发券</span></p><p><span style=\"font-family:'微软雅黑', sans-serif;\"><br></span></p><p><span style=\"font-family:'微软雅黑', sans-serif;\">2、用户行为触发：</span></p><p><span style=\"font-family:'微软雅黑', sans-serif;\">活动中心定义活动规则、选择行为触发场景；</span></p><p><span style=\"font-family:'微软雅黑', sans-serif;\">业务系统将用户触发行为（比如预约维保）上报给大数据，大数据通知活动中心发券</span></p><p><span style=\"font-family:'微软雅黑', sans-serif;\"><br></span></p><p><span style=\"font-family:'微软雅黑', sans-serif;\">3、C端主动参与：</span></p><p><span style=\"font-family:'微软雅黑', sans-serif;\">BIMC双月活动/BIMC会员周活动/BIMC单店机动券活动</span></p><p><span style=\"font-family:'微软雅黑', sans-serif;\"><br></span></p><p><span style=\"font-family:'微软雅黑', sans-serif;\">4、C端主动领取：</span></p><p><span>勾选后可以在对应点位露出，供用户点击领取</span></p>",bo="<p><span>非【C端主动参与】，隐藏【tab界面配置】，隐藏【tab基础配置-分享信息】【tab基础配置-SEO信息】；</span></p><p><span>反之，C端活动需展示上述配置项</span></p>",bp="<p><span style=\"font-family:'Arial-BoldMT', 'Arial Bold', 'Arial', sans-serif;font-weight:700;color:#0EAFC0;\">续保活动，</span></p><p><span style=\"font-family:'Arial-BoldMT', 'Arial Bold', 'Arial', sans-serif;font-weight:700;color:#0EAFC0;\">触发方式：可配置后台统一推送、用户行为触发的活动，其他2个选项置灰不可选</span></p>",bq="9",br="0dfdc86c6a1049428edd4a74dda53f26",bs="互斥套餐：",bt="<p><span>选择互斥套餐的，需剔除已享有该套餐的客户</span></p>",bu="数据来源",bv="<p><span>E3S售后套餐库</span></p>",bw="10",bx="abfbb39c6f0e41bba9044fead9fa219b",by="* 互斥活动ID：",bz="<p><span>选择互斥活动id的，需剔除已参与活动的客户;</span></p><p><span>选择互斥活动ID，该活动ID中关联的卡券都互斥</span></p>",bA="<p><span>活动中心</span></p>",bB="11",bC="88798d6b391a4a5eb450aba6646c7269",bD="* 大数据人群包选择：",bE="<p><span style=\"font-family:'PingFangSC-Regular', 'PingFang SC', sans-serif;\">业务子板块：续保，</span></p><p><span style=\"font-family:'PingFangSC-Regular', 'PingFang SC', sans-serif;\">VIN去重；</span></p><p><span style=\"font-family:'PingFangSC-Regular', 'PingFang SC', sans-serif;\">A类客户、H类客户重叠，过滤A类，以H类为准--&gt;做不到！</span></p><p><span style=\"font-family:'ArialMT', 'Arial', sans-serif;color:#333333;\"><br></span></p><p><span style=\"font-family:'ArialMT', 'Arial', sans-serif;color:#333333;\"><br></span></p><p><span style=\"font-family:'ArialMT', 'Arial', sans-serif;color:#333333;\">1、必填：后台统一推送；</span></p><p><span style=\"font-family:'ArialMT', 'Arial', sans-serif;color:#333333;\">2、非必填：C端主动参与活动；C端主动领取；商城售后、商城周边非必填；商城售后的活动属性包含了VIN（车，人+车），则必填人群包；</span></p><p><span style=\"font-family:'ArialMT', 'Arial', sans-serif;color:#333333;\">3、用户行为触发无需填写</span></p>",bF="<p><span>CDP人群包</span></p>",bG="<p><span style=\"font-family:'PingFangSC-Regular', 'PingFang SC', sans-serif;color:#6300BF;\">填写完【大数据人群包】，实时查询人群包接口，返回【目标用户清单】</span></p><p><span style=\"font-family:'PingFangSC-Regular', 'PingFang SC', sans-serif;color:#6300BF;\"><br></span></p><p><span style=\"font-family:'PingFangSC-Regular', 'PingFang SC', sans-serif;\">拉取A人群包，B人群包，两个人群包都有同一用户a</span></p><p><span style=\"font-family:'PingFangSC-Regular', 'PingFang SC', sans-serif;\">同一个活动，用户a去重</span></p>",bH="12",bI="45d05809562742d1b7707698dadcae61",bJ="下一步",bK="<p><span>点击下一步，跳转step2：关联卡券</span></p>",bL="13",bM="c8708f14cadf4222ad8fd02953439957",bN="活动配置",bO="前置条件",bP="<p><span>选择品牌，选择对应品牌下的卡券</span></p>",bQ="<p><span>必填；填写后不可编辑修改；</span></p><p><span>在活动列表-复制后可编辑修改</span></p>",bR="14",bS="6999f805198748eb98622459316df44f",bT="* 活动类型：",bU="<p><span style=\"font-family:'PingFangSC-Regular', 'PingFang SC', sans-serif;color:rgba(217, 0, 27, 0.847058823529412);\">活动类型：1、活动主体划分，2、按照卡券触发方式划分</span></p>",bV="15",bW="b90a979822e440f195400186aed474ae",bX="否",bY="<p><span>选择否，隐藏下面的配置</span></p>",bZ="16",ca="b60927c3fe824d59bfc88c46124ce8e8",cb="是",cc="<p><span>选择“是”，短信/APP消息/小程序站内信 ，必填其中一个</span></p>",cd="17",ce="f1bbd62178f04c459334b78a09cfd875",cf="店端-->用户",cg="<p><span>厂家发券给店，用户是店端去圈</span></p>",ch="<p><span>待拓展；按钮置灰，不可勾选</span></p>",ci="18",cj="f6698e8d094a4fa18eaba4b611389204",ck="* 活动主体：",cl="<p><span>1、前三个选项互斥，即只能选中其中一个；</span></p><p><span>2、支持单选，即可以只选择四个选项的其中一个；</span></p><p><span>3、任意选项都可以加商城，也可以单选商城</span></p>",cm="<p><span style=\"font-family:'Arial-BoldMT', 'Arial Bold', 'Arial', sans-serif;font-weight:700;color:#0EAFC0;\">续保活动，</span></p><p><span style=\"font-family:'Arial-BoldMT', 'Arial Bold', 'Arial', sans-serif;font-weight:700;color:#0EAFC0;\">活动主体：默认厂家--&gt;用户</span></p><p><span style=\"font-family:'Arial-BoldMT', 'Arial Bold', 'Arial', sans-serif;font-weight:700;color:#0EAFC0;\">其他选项置灰不可选</span></p>",cn="19",co="3786e6c0f5214fccae76ca009b8eb290",cp="* 是否发送消息提醒：",cq="<p><span style=\"font-family:'PingFangSC-Regular', 'PingFang SC', sans-serif;color:#333333;\">C端主动领取，隐藏消息提醒配置</span></p>",cr="20",cs="c96bc159ee1a4f1f94d7870383fabb11",ct="C端主动领取",cu="<p><span>新增/更新活动信息时，同步给卡券/商城，卡券去执行卡券的领券点位，商城去执行商城的领券点位</span></p>",cv="21",cw="752296cf43464a3b80ee5272ba4c6c75",cx="活动政策（对客户）：",cy="<p><span>20240620新增字段</span></p>",cz="22",cA="b72fd59a155945809ed83526b07f5242",cB="活动补贴（对专营店）：",cC="23",cD="f7e5b52adf6c44ffa1298efe486118a3",cE="(形状)",cF="<p><span>显示注释文案：可以配置【后台统一推送】、【用户行为触发】、【C端主动参与活动】、【C端主动领取】四类活动</span></p>",cG="24",cH="a9deb1cc287b4665a2dfa1ed22b1bd25",cI="<p><span>显示注释文案：可以配置【C端主动参与活动--&gt;BIMC单店机动券活动】这一个活动</span></p>",cJ="<p><span>与BIMC单店机动券联动</span></p>",cK="25",cL="7f5354d2988e48b0a3f62d49c033c251",cM="<p><span>显示注释文案：可以配置【后台统一推送】、【用户行为触发】、【C端主动领取】三类活动</span></p>",cN="<p><span>（不需要展示给用户）</span></p><p><span>商城分售后跟周边</span></p><p><span>售后就是要车型、门店，周边不用</span></p>",cO="26",cP="5a97c41ef2f34f76a0b72ae667ffd6a2",cQ="27",cR="14c49262a64147b9a028858c049c21b5",cS="续保活动",cT="<p><span>续保活动，</span></p><p><span>活动主体：默认厂家--&gt;用户</span></p><p><span>触发方式：可配置后台统一推送、用户行为触发的活动，其他2个选项置灰不可选</span></p>",cU="28",cV="98993efe539649d8a3fd3484400be61e",cW="* 活动奖品：",cX="<p><span>1-卡券中心-卡券，2-续保权益</span></p>",cY="29",cZ="d1d78a4fe5a645e3ac68e844947fc2c6",da="续保权益",db="<p><span>选择续保权益，显示“权益中是否包含取送车卡券”</span></p>",dc="<p><span>续保活动+续保权益，</span></p><p><span>只能配置“用户行为触发”的活动，其他活动置灰不可选</span></p>",dd="30",de="97d6abf90b8047749895e71371b693ff",df="卡券中心-卡券",dg="<p><span>选择卡券中心-卡券，</span></p><p><span>隐藏关联权益的tab；</span></p>",dh="<p><span>续保活动+卡券，</span></p><p><span>只能配置“后台统一推送”的活动，其他活动置灰不可选</span></p>",di="31",dj="7e89377469dd42739457b8d4e0a05023",dk="选人",dl="<p><span style=\"font-family:'PingFangSC-Regular', 'PingFang SC', sans-serif;color:#555555;\">选择根据“人”发放或领取卡券，必填用户标识，</span><span style=\"color:#333333;\">至少勾选1个选项；</span></p><p><span style=\"font-family:'PingFangSC-Regular', 'PingFang SC', sans-serif;color:#555555;\">可复选，</span><span style=\"font-family:'PingFangSC-Regular', 'PingFang SC', sans-serif;color:#333333;\">选项之间关系为“且”，即用户的</span><span style=\"font-family:'PingFangSC-Regular', 'PingFang SC', sans-serif;color:#555555;\">手机号和oneid保持一致时才可发放或者领取卡券</span></p>",dm="32",dn="3a88b838a21847f99464bcfa95c30cff",dp="选人+车",dq="<p><span style=\"font-family:'PingFangSC-Regular', 'PingFang SC', sans-serif;color:#555555;\">选择根据“人+车”发放或领取卡券，必填用户标识；</span><span style=\"color:#333333;\">手机号和oneid必须勾选其一，默认勾选VIN、</span><span style=\"font-family:'PingFangSC-Regular', 'PingFang SC', sans-serif;color:#555555;\">按钮置灰不可编辑</span></p><p><span style=\"font-family:'PingFangSC-Regular', 'PingFang SC', sans-serif;color:#333333;\">选项之间关系为“且”，即</span><span style=\"font-family:'PingFangSC-Regular', 'PingFang SC', sans-serif;color:#555555;\">“人+车”</span><span style=\"font-family:'PingFangSC-Regular', 'PingFang SC', sans-serif;color:#333333;\">2个字段要保持</span><span style=\"font-family:'PingFangSC-Regular', 'PingFang SC', sans-serif;color:#555555;\">一致时才可发放或者领取卡券</span></p>",dr="33",ds="512880de10d841e78b78d885652ab78a",dt="* 活动属性：",du="<p><span style=\"font-family:'PingFangSC-Regular', 'PingFang SC', sans-serif;\"><br></span></p><p><span style=\"font-family:'PingFangSC-Regular', 'PingFang SC', sans-serif;\">单选，1-选人，2-选车，3-选人+车；</span></p><p><span style=\"font-family:'PingFangSC-Regular', 'PingFang SC', sans-serif;color:#D9001B;\"><br></span></p><p><span style=\"font-family:'PingFangSC-Regular', 'PingFang SC', sans-serif;color:#D9001B;\">1、必填：后台统一推送、C端主动参与活动（默认VIN）、C端主动领取、用户行为触发；</span><span style=\"font-family:'PingFangSC-Regular', 'PingFang SC', sans-serif;color:#0EAFC0;\">业务子板块：续保，默认选车；</span><span style=\"font-family:'ArialMT', 'Arial', sans-serif;color:#00C297;\">业务子板块：取送车，默认选车</span></p><p style=\"line-height:24px;\"><span style=\"font-family:'PingFangSC-Regular', 'PingFang SC', sans-serif;color:#D9001B;\">2、活动主体-商城售后时，活动属性为 非必填；商城周边，默认选人；</span></p><p style=\"line-height:24px;\"><span style=\"font-family:'PingFangSC-Regular', 'PingFang SC', sans-serif;color:#D9001B;\">3、复选商城售后、商城周边，活动属性--&gt;只能选择交集，选人</span></p><p style=\"line-height:24px;\"><span style=\"font-family:'PingFangSC-Regular', 'PingFang SC', sans-serif;color:#D9001B;\"><br></span></p><p style=\"line-height:24px;\"><span style=\"font-family:'PingFangSC-Regular', 'PingFang SC', sans-serif;\">1-选择根据“人”发放或领取卡券，用户默认oneid，按钮置灰不可编辑；</span></p><p style=\"line-height:24px;\"><span style=\"font-family:'PingFangSC-Regular', 'PingFang SC', sans-serif;\">2-选择根据“车”发放或领取卡券，用户标识默认为VIN，按钮置灰不可编辑；</span></p><p style=\"line-height:24px;\"><span style=\"font-family:'PingFangSC-Regular', 'PingFang SC', sans-serif;\">3-选择根据“人+车”发放或领取卡券，用户标识默认oneid、VIN，按钮置灰不可编辑</span></p><p style=\"line-height:24px;\"><span style=\"font-family:'PingFangSC-Regular', 'PingFang SC', sans-serif;\">选项之间关系为“且”，即“人+车”2个字段要保持一致时才可发放或者领取卡券</span></p>",dv="34",dw="6c9c87f06c184fa990fd7bb482ca3a5b",dx="选车",dy="<p><span style=\"font-family:'PingFangSC-Regular', 'PingFang SC', sans-serif;color:#555555;\">选择根据“车”发放或领取卡券，用户标识默认为VIN，按钮置灰不可编辑</span></p>",dz="35",dA="1db2c6b6e8ee4e7aaaf34cf511a3b350",dB="关联车系车型：",dC="<p><span>售后活动的颗粒度到18位码</span></p>",dD="<p><span style=\"font-family:'PingFangSC-Regular', 'PingFang SC', sans-serif;color:#333333;\">&nbsp;</span><span style=\"font-family:'PingFangSC-Regular', 'PingFang SC', sans-serif;color:#D9001B;\">【基本信息-</span><span style=\"color:#D9001B;\">活动车型的取值-以活动为准，多张卡券统一设置车型】展示该填写项，选择其他选项则隐藏该填写项</span></p>",dE="<p><span>续保以后可能有单车系的活动</span></p>",dF="36",dG="14cf43c304e44007aed77c3fb4c8d9e8",dH="选择车系车型",dI="<p><span>查看活动状态下，按钮变更为 查看车系车型，点击后跳转弹窗（图8），选项置灰、不可编辑</span></p>",dJ="37",dK="e29a129d98244d3b8e6ac7068f7debf3",dL="* 业务子版块：",dM="<p><span>字典维护，</span></p><p><span>1-维保活动，2-续保活动，3-取送车活动</span></p>",dN="38",dO="b8f10b61ab474fdea13ac18f17fd756a",dP="是否到了活动开始时间自动启用？",dQ="<p><span style=\"font-family:'PingFangSC-Regular', 'PingFang SC', sans-serif;color:#D9001B;\">新增“是否到了活动开始时间自动启用？”（售前、售后都要改）</span></p><p><span style=\"font-family:'PingFangSC-Regular', 'PingFang SC', sans-serif;color:#D9001B;\">是--&gt;自动启用</span></p><p><span style=\"font-family:'PingFangSC-Regular', 'PingFang SC', sans-serif;color:#D9001B;\">否--&gt;活动时间到了也不启用</span></p>",dR="39",dS="294579b397884323afe3d3a1433af4a2",dT="* 行为触发场景：",dU="<p><span>用户产生什么行为，就给用户发券</span></p><p><span>----------------</span></p><p><span>step1、活动中心定义规则：</span></p><p><span>选择行为触发场景；新增/更新信息同步给业务系统</span></p><p><span>step2、业务系统响应：</span></p><p><span>业务系统实时监测用户数据；</span></p><p><span>step3、业务系统行为上报：</span></p><p><span>当用户产生行为时，业务系统查询用户是否活动目标用户，如是，则将行为、用户信息上报给活动中心</span></p><p><span>step4、活动中心调用卡券中心发券接口进行定向发券</span></p>",dV="<p><span>触发方式--&gt;用户行为触发</span></p>",dW="<p><span>字典维护</span></p>",dX="<p><span style=\"color:#333333;\">具体流程见【需求分析方案】--&gt;【以此为准】方案1 活动中心发券 用户行为触发/卡券激活 流程图2024-06-06</span></p>",dY="40",dZ="63541d43de97430facb5b362540f5908",ea="<p><span>展示行为触发场景列表，</span></p><p><span>【腾讯文档】用户行为触发、卡券激活 场景列表</span></p><p><span>https://docs.qq.com/sheet/DZVVvU0tEQWFEZ1Nk?tab=BB08J2</span></p>",eb="41",ec="7e630f2b4911497bbe31b11dbb8634be",ed="续保保单签单",ee="<p><span>行为触发场景-续保</span></p>",ef="42",eg="36a602890bbb4e13834becb96b2acf01",eh="E3S续保套餐销售单",ei="43",ej="42163fb2cfb04af98bb727f476af2cd9",ek="已配置卡券：",el="<p><span>配置序号--按照已配置的时间顺序排列；</span></p>",em="<p><span>配置卡券，即显示该列表</span></p>",en="<p><span>配置单张卡券不显示【批量选择卡券互斥】按钮和全选框</span></p>",eo="44",ep="0451fc9036554ddfad388660f38ad258",eq="* 关联卡券ID：",er="<p><span>选择品牌，选择对应品牌下的卡券；</span></p><p><span>不选品牌，先选卡券会提示“请先选择品牌”</span></p>",es="<p><span>C端活动-选择多张卡券，前端落地页/领券结果页一 一对应</span></p>",et="45",eu="b8f077a0cb844d1597fe6b8b5c95a11f",ev="车型：",ew="<p><span style=\"font-family:'PingFangSC-Regular', 'PingFang SC', sans-serif;color:rgba(0, 0, 0, 0.847058823529412);\">基本信息--&gt;活动车型取值--&gt;选择【1-</span><span style=\"font-family:'PingFangSC-Regular', 'PingFang SC', sans-serif;color:#333333;\">以卡券中心配置的为准】、【3-以活动为准，多张卡券统一设置车型】按钮为【查看】；</span></p><p><span style=\"font-family:'PingFangSC-Regular', 'PingFang SC', sans-serif;color:#333333;\">2-以活动为准，每张卡券单独设置车型，按钮为【编辑】，仅可</span><span style=\"font-family:'PingFangSC-Regular', 'PingFang SC', sans-serif;\">在</span><span style=\"font-family:'微软雅黑', sans-serif;font-weight:400;\">卡券已配置车型的基础上，进行减少</span></p>",ex="<p><span style=\"font-family:'PingFangSC-Regular', 'PingFang SC', sans-serif;color:rgba(0, 0, 0, 0.847058823529412);\">活动类型单选【C端】的--&gt;按钮：查看车型；</span></p><p><span style=\"font-family:'ArialMT', 'Arial', sans-serif;color:#D9001B;\">商城周边隐藏门店、车型</span></p>",ey="46",ez="05a9e9279f7a449da15d964c129d94e0",eA="门店：",eB="<p><span style=\"font-family:'PingFangSC-Regular', 'PingFang SC', sans-serif;color:rgba(0, 0, 0, 0.847058823529412);\">基本信息--&gt;活动车型取值--&gt;选择【1-</span><span style=\"font-family:'PingFangSC-Regular', 'PingFang SC', sans-serif;color:#333333;\">以卡券中心配置的为准】、【3-以活动为准，多张卡券统一设置</span><span style=\"font-family:'PingFangSC-Regular', 'PingFang SC', sans-serif;color:rgba(0, 0, 0, 0.847058823529412);\">门店</span><span style=\"font-family:'PingFangSC-Regular', 'PingFang SC', sans-serif;color:#333333;\">】按钮为【查看】；</span></p><p><span style=\"font-family:'PingFangSC-Regular', 'PingFang SC', sans-serif;color:#333333;\">选择【2-以活动为准，每张卡券单独设置</span><span style=\"font-family:'PingFangSC-Regular', 'PingFang SC', sans-serif;color:rgba(0, 0, 0, 0.847058823529412);\">门店】</span><span style=\"font-family:'PingFangSC-Regular', 'PingFang SC', sans-serif;color:#333333;\">，按钮为【编辑】，可</span><span style=\"font-family:'PingFangSC-Regular', 'PingFang SC', sans-serif;\">在</span><span style=\"font-family:'微软雅黑', sans-serif;font-weight:400;\">卡券已配置车型的基础上，进行增减（卡券无二网店）</span></p>",eC="<p><span style=\"font-family:'PingFangSC-Regular', 'PingFang SC', sans-serif;color:rgba(0, 0, 0, 0.847058823529412);\">活动类型单选【C端】的--&gt;按钮：查看门店；</span></p><p><span style=\"font-family:'ArialMT', 'Arial', sans-serif;color:#D9001B;\">商城周边隐藏门店、车型</span></p>",eD="47",eE="cffcd29150a7465eb3ec262ca91d0331",eF="<p><span>点击下一步，跳转step3：活动对象</span></p>",eG="48",eH="08b0324c122c4694b55aaf4c68be4c8b",eI="选择卡券",eJ="<p><span>点击跳转图1，</span></p><p><span>只能选择售后营销-上门取送车场景下的卡券</span></p>",eK="<p><span>查看活动状态下，反选卡券id、卡券名称，选择卡券按钮隐藏</span></p>",eL="49",eM="a3b56b0dcefb4da1ab29e8bd6c365a37",eN="* 卡券策略：",eO="<p><span>同一个卡券不能加入活动时间重叠的不同活动；</span><span style=\"color:#D9001B;\">【C端主动参与活动】不受此限制</span></p><p><span><br></span></p><p><span>活动时间有重叠的情况下，</span></p><p><span>重叠：活动1开始-截止时间6.5-6.30，活动2时间6.1-7.1 </span></p><p><span><br></span></p><p><span>活动1【首先】设置了A卡券与B卡券互斥；</span></p><p><span><br></span></p><p><span>当活动2 设置B卡券与A卡券叠加时，点击提交时进行校验，提示：设置失败！活动时间重叠的情况下，活动1已经设置券B与券A叠加</span></p><p><span><br></span></p><p><span>按照创建时间，以先设置的为准；后设置的读取先设置的</span></p>",eP="<p><span>续保，</span></p><p><span>卡券策略：与指定互斥、与全部互斥，无互斥</span></p>",eQ="50",eR="b76d4af7d4f14ab8bc4859dca7f419bb",eS="与指定券叠加",eT="<p><span>与指定券叠加/互斥，才显示卡券搜索、卡券列表</span></p>",eU="51",eV="3d907a8918a648bbb9c759afe656c611",eW="与指定券互斥",eX="52",eY="06b0e9fa3c4a42849f9c8ebe69b63c41",eZ="与全部券叠加",fa="<p><span>与现有的卡券中心卡券、后续卡券中心新增的卡券都叠加；</span></p><p><span>后续新增的叠加卡券id，更新在叠加卡券列表中（叠加列表-已选），按照时间倒序排列</span></p>",fb="53",fc="e5d5df12f2d24a79ad6a0e98d6d47d16",fd="与全部券互斥",fe="<p><span>与现有的卡券中心卡券、后续卡券中心新增的卡券都互斥；</span></p><p><span>后续新增的互斥卡券id，更新在互斥卡券列表中（叠加列表-已选），按照时间倒序排列</span></p>",ff="54",fg="08958521ef154505ab098ac3c274245e",fh="查看门店",fi="<p><span>续保 默认 以卡券为准</span></p>",fj="55",fk="fe758505ea3346309173c9b5109db6e8",fl="查看车型",fm="56",fn="58ebf259ae364a6792bd5e99adb88148",fo="取送车活动",fp="<p><span>取送车活动，</span></p><p><span>活动奖品 默认勾选卡券中心-卡券，</span></p><p><span>其他选项置灰不可选</span></p>",fq="57",fr="eab6d00841974a68950f66fa9ca3814f",fs="取送车双月活动",ft="<p><span>字典维护：取送车活动后台统一推送；</span></p>",fu="<p><span>取送车+后台统一推送</span></p>",fv="58",fw="166567424cf34d30991be889a037e55f",fx="* 是否活动互斥：",fy="<p><span>设置活动互斥，即活动1关联的卡券和活动2关联的卡券都互斥；</span></p><p><span>这里的互斥，是指【C端主动参与活动】的领券互斥，以及E3S、商城的用券互斥</span></p><p><span>------------</span></p><p><span style=\"font-family:'PingFangSC-Regular', 'PingFang SC', sans-serif;\">同时设置了活动1和活动2，</span></p><p><span style=\"font-family:'PingFangSC-Regular', 'PingFang SC', sans-serif;\">活动1和活动2互斥，只设置活动1的互斥，未设置活动2的互斥；编辑/更新活动2时，把活动1的互斥带出来</span></p>",fz="<p><span style=\"font-family:'PingFangSC-Regular', 'PingFang SC', sans-serif;\">（20240426与IS李金刚会议确认）</span></p><p><span style=\"font-family:'PingFangSC-Regular', 'PingFang SC', sans-serif;\">互斥活动通过活动id去规范，卡券承接套餐、备件、工时；</span></p><p><span style=\"font-family:'PingFangSC-Regular', 'PingFang SC', sans-serif;\">初始化任务：</span></p><p><span style=\"font-family:'PingFangSC-Regular', 'PingFang SC', sans-serif;\">1、需创建历史活动，把已有卡券关联起来；</span></p><p><span style=\"font-family:'PingFangSC-Regular', 'PingFang SC', sans-serif;\">2、现有的非卡券需要转卡券形式（TBD，E3S、商城）</span></p>",fA="59",fB="6887c34a802043e89dab32d066d54d33",fC="<p><span>选择否，隐藏下面配置项</span></p>",fD="60",fE="d2c4e0cd62d4497c991e28df965054f7",fF="与全部活动互斥",fG="<p><span>业务场景不需要</span></p><p><span><br></span></p><p><span>与现有的活动id（未启用/已启用）、后续活动中心新增的活动id都互斥；</span></p><p><span>后续新增的互斥活动id，更新在该活动id的互斥活动列表中（互斥列表-已选），按照时间倒序排列</span></p>",fH="61",fI="ef1d4f4deb4040e1b8fb69c491352ab7",fJ="查看全部互斥活动",fK="<p><span>点击跳转图9</span></p>",fL